// === DISPATCH: prepare les articles + dossier de sortie unique ===
const input = $input.first().json;
const body = input.body || input;
const mode = body.mode || 'screening';
const articles = body.articles || [];
const question = body.question || '';
const criteria = body.criteria || '';
const extractFields = body.extract_fields || null;
// Format de sortie choisi par l'user (ris/nbib/bib) - RIS par defaut pour back-compat
const outputFormat = ((body.output_format || 'ris') + '').toLowerCase().trim();
// CADENCE_v1 : intervalle d'emission des appels au modele, calcule par le moteur
// (src/cadence.py) et injecte dans le corps du lancement par le proxy. Le nœud qui
// appelle le modele N'ATTEND PAS ses reponses : il emet a intervalle fixe. Mesure du
// 2026-08-10 : a 200 ms fixes, 500 requetes arrivaient en 116 s pour un travail de
// 975 s ; a 12 772 references, plus de onze mille requetes attendaient en meme temps,
// une socket et un fil chacune, et le moteur devenait injoignable.
// UNE CADENCE ABSENTE N'EST PAS UN ZERO MESURE (2026-10-20, P05 de l'inventaire des defauts
// restants). Ce qui etait faux : un corps sans `pacing_ms` (le relais n'a pas pu calculer la cadence
// et rend le corps tel quel) donnait 0, et le repli prudent du nœud d'appel de l'extraction
// (1 800 ms) n'etait jamais atteint. MESURE sur la base e332a31 (vrais nœuds) : chaque appel au
// modele partait a 0 ms. Ce qui change : absente ou illisible, la cadence reste absente (null) ;
// une cadence recue, zero compris, passe telle quelle, bornee a zero.
const __cadenceRecue = parseInt(body.pacing_ms, 10);
const pacingMs = Number.isFinite(__cadenceRecue) ? Math.max(0, __cadenceRecue) : null;
const validFormats = ['ris', 'nbib', 'bib'];
const safeOutputFormat = validFormats.includes(outputFormat) ? outputFormat : 'ris';


console.log('Module: ' + mode + ' avec ' + articles.length + ' articles');

if (articles.length === 0) {
  return [{ json: { error: 'Aucun article fourni', mode } }];
}

// Generer un dossier de sortie unique : /desktop/ultralab-module-<mode>-<YYYYMMDD-HHMM>/
const now = new Date();
const pad = n => String(n).padStart(2, '0');
const timestamp = now.getFullYear() + pad(now.getMonth()+1) + pad(now.getDate()) + '-' + pad(now.getHours()) + pad(now.getMinutes());

// RUN_UID_v1 : deux runs du MEME mode lances dans la MEME minute ecrasaient le meme dossier
// (multi-run, double clic). On ajoute l'identifiant d'execution n8n, qui est le SEUL suffixe
// utilisable ici : « Prepare Articles » et « Build Async Response » calculent ce nom chacun de
// leur cote (branches paralleles) et doivent tomber sur le MEME resultat ; un suffixe aleatoire
// les ferait diverger et le client ne retrouverait plus son dossier. Si l'identifiant n'est pas
// disponible, on retombe sur l'ancien nom (pas de suffixe) plutot que sur une valeur divergente.
let _execId = '';
try { _execId = String(($execution && $execution.id) || ''); } catch (e) { _execId = ''; }
_execId = _execId.replace(/[^A-Za-z0-9]/g, '').slice(0, 12);
const runSuffix = _execId ? ('-e' + _execId) : '';
const folderName = 'ultralab-module-' + mode + '-' + timestamp + runSuffix;
// D.8 custom output_folder : si l'user a choisi un dossier custom via UI, on l'utilise.
// Sinon default : /desktop/ultralab-module-<mode>-<timestamp>/
const userOutputFolder = (body.output_folder && typeof body.output_folder === 'string') ? body.output_folder.trim().replace(/\/+$/, '') : '';
let outputFolder;
// PROJETS HORS BUREAU (0.5.0) : /projets/<dossier> est une racine valide au meme titre
// que /desktop. Sans cette ligne, un projet range ailleurs que sur le Bureau retombait
// silencieusement dans la branche « defaut » et ecrivait a la racine du Bureau.
if (userOutputFolder && (userOutputFolder.startsWith('/desktop') || userOutputFolder.startsWith('/projets/'))) {
  // Path Docker valide (commence par /desktop) -> on append le sub-folder mode-timestamp
  outputFolder = userOutputFolder + '/' + folderName;
} else {
  outputFolder = '/desktop/' + folderName;
}
console.log('Dossier de sortie : ' + outputFolder);

// Enrichir le premier article avec question/criteres + output_folder partout
const enriched = articles.map((a, i) => {
  const article = { ...a, output_folder: outputFolder, _module_mode: mode, _folder_name: folderName };
  if (i === 0) {
    article.question = question;
    article.criteria = criteria;
    article.prefilter_enabled = false;
    if (extractFields) article.extract_fields = extractFields;
    // Skip flags : on saute les autres etapes (juste le module demande)
    article.skip_ranking = mode !== 'ranking';
    article.skip_clustering = mode !== 'clustering';
    article.skip_screening = mode !== 'screening';
    article.skip_pdf = mode !== 'pdf-fetch';
    article._output_format = safeOutputFormat;
    // Absente (P05, 2026-10-20), la cadence n'est pas posee, et celle qu'un corpus relance porte
    // de son run precedent (d'un autre module, peut-etre) est retiree : le nœud d'appel de chaque
    // module prend son repli (le tri, le classement et le regroupement aussi, depuis le tour 2 du
    // lot : leur « Prepare Batches » ne change plus l'absence en zero).
    if (pacingMs === null) delete article._pacing_ms;
    else article._pacing_ms = pacingMs;
  }
  // Pour le PDF fetch, marquer tous comme Include si pas de screening_decision
  if (mode === 'pdf-fetch' && !article.screening_decision) {
    article.screening_decision = 'Include';
  }
  return { json: article };
});


// PROGRESS_START_v1
try { await this.helpers.httpRequest({ method:'POST', url:'http://host.docker.internal:8080/api/module-progress/start', body:JSON.stringify({mode:mode, total:articles.length, label:mode}), headers:{'Content-Type':'application/json'}, timeout:3000 }); } catch(e) {}
return enriched;

// MODELE_REELLEMENT_EMPLOYE_v1 : le fichier de methodes declare le modele qui a SERVI.
// MESURE DU 2026-09-04 sur un run reel : `chat_model: gemma4:e4b` declare, 3 807 appels vers
// `qwen3.8:27b` dans le journal d'audit de la meme session. Le noeud lisait le reglage LOCAL
// alors que le poste tourne en mode distant. Un fichier de methodes qui nomme un modele qui n'a
// pas tourne rend la revue irreproductible, et rien ne le signale a la lecture.
// LA REGLE EST CELLE DU MOTEUR (settings.resolve_model) : en mode distant, `remote_<cle>` prime
// si elle est renseignee ; vide, on retombe sur le reglage local. Si l'une des deux change, il
// faut changer l'autre : c'est pourquoi la source de verite est nommee ici.
function __ulModele(c, cle) {
  if (c && c.mode === 'distant') {
    var r = c['remote_' + cle];
    if (r && String(r).trim()) return String(r).trim();
  }
  return c ? c[cle] : undefined;
}
// TYPE_PUBLICATION_REEL_v1 : le type declare vient de la notice, plus d'une constante.
// MESURE DU 2026-09-04 : les fichiers livres declaraient 4 306 notices sur 4 306 comme
// « Journal Article », dont 400 enregistrements d'essai et prepublications. Confondre un
// protocole d'essai non publie avec un article a comite de lecture est une faute de methode,
// qui remonte au diagramme PRISMA. L'information existait pourtant : les sources posent
// `publication_type` et `publication_types` sur chaque notice, et personne ne les lisait.
// On retombe sur la valeur historique quand le type est INCONNU : on cesse d'affirmer, on
// n'invente pas pour autant.
function __ulTypes(a) {
  const out = [];
  const brut = a && (a.publication_types || a.publication_type);
  if (Array.isArray(brut)) { for (const t of brut) { if (t) out.push(String(t)); } }
  else if (brut) out.push(String(brut));
  return out.length ? out : ['Journal Article'];
}
// PROVENANCE_UNE_REGLE_v1 (2026-10-16) : la ligne « SO  - [source:<base>] » par une seule regle.
// CE QUI ETAIT FAUX : quatre ecrivains du fichier MEDLINE, quatre regles. « Generate NBIB »
// lisait `_source || source` sans rognage et ecrivait « [source:] » pour une notice sans
// provenance ; « Assemble Results » et « Build Export » lisaient `_source` SEUL ; l'ecrivain du
// moteur (src/merge_corpus.py, `_nbib`) n'ecrivait aucune ligne. Les notices de l'application
// portent `source` sans `_source` : un fichier de resultats repris comme corpus perdait sa
// provenance. MESURE (tests/test_provenance_ecrite_par_les_quatre_ecrivains.py, neuf formes de
// notice, chaque ecrivain execute) : 4, 6, 6 et 7 formes mal ecrites selon l'ecrivain, dont la
// ligne « [source:] », que le lecteur relit comme une base de ce nom.
// LA REGLE, celle de `merge_corpus._provenance` : la premiere valeur non vide, une fois rognee,
// de `_source` puis de `source`. Aucune : pas de ligne, plutot qu'une provenance inventee. Si
// l'un des quatre ecrivains change de regle, il faut changer les trois autres.
function __ulProvenance(a) {
  const cles = ['_source', 'source'];
  for (let i = 0; i < cles.length; i++) {
    const v = a[cles[i]];
    // 2026-10-19 (lot « references », P52) : une valeur qui n'est pas une chaine (booleen, nombre,
    // liste, objet) n'est pas une provenance, et la cle suivante est lue. CE QUI ETAIT FAUX :
    // String(v) ecrivait « true », « a,b » ou « [object Object] », et le moteur « True » ou
    // « ['a', 'b'] » (merge_corpus._provenance) : les quatre copies divergeaient. Le test du
    // nul et de l'absent est compris dans celui-ci.
    if (typeof v !== 'string') continue;
    const t = v.trim();
    if (t) return t;
  }
  return '';
}
// RESUME_ENTIER_v1 : le resume n'est plus coupe a 2 000 caracteres.
// MESURE DU 2026-09-04 sur un run reel de 3 804 references : le .ris livre plafonnait a
// EXACTEMENT 2 000 caracteres, 867 notices assises pile sur la borne, quand le .nbib du
// MEME run, ecrit par le MEME noeud, montait a 18 690. La coupe ne venait donc pas de la
// source. Cout : 22,6 % des resumes ampute, environ 417 000 caracteres perdus, et rien ne
// distinguait un resume court d'un resume coupe. Ni RIS ni BibTeX n'imposent de limite.
// ETAPE_DECLAREE_v1 : ce nœud DIT qu'il commence, et qu'il finit.
// Quatre runs de suite se sont arretes entre le dernier appel au modele et
// l'assemblage sans laisser la moindre trace : ni journal, ni enregistrement
// d'execution, ni dossier de sortie. Impossible de dire quel nœud les avait
// avales. Une declaration d'entree et de sortie change « le run s'est evapore »
// en « le run est entre ici et n'en est jamais ressorti ».
const __etMode = String((($input.all()[0] || {}).json || {})._module_mode || 'unknown');
async function __etape(phase, n) {
  try {
    await this.helpers.httpRequest({
      method: 'POST', url: 'http://host.docker.internal:8080/api/etape',
      headers: { 'Content-Type': 'application/json' }, timeout: 8000,
      body: JSON.stringify({ mode: __etMode, noeud: 'Assemble Results',
                             phase: phase, n: n })
    });
  } catch (__e) {}
}
await __etape.call(this, 'entree', $input.all().length);
// ETAPE_TOUS_CHEMINS_v1 : la sortie est declaree par TOUS les chemins.
//
// Premiere version : elle etait posee avant le DERNIER `return` du nœud. Or celui de
// la seconde relecture a un `return` ANTICIPE, emprunte chaque fois que la double
// relecture est desactivee, c'est-a-dire le cas courant. Le nœud ne declarait donc
// jamais sa sortie, et l'instrument le montrait « entre, jamais ressorti » alors
// qu'il etait sorti normalement. Un instrument qui accuse un innocent est pire
// qu'une absence d'instrument : on cherche la panne la ou il la designe.
try {
// === ASSEMBLE + EXPORT MODULE RESULTS ===
// Refactor 0.4.3 : le monolithe par phases (stats / RIS / XLSX / rapport melanges par de
// longs if(mode===...)) est reorganise en ROUTEUR PAR MODULE. La logique propre a chaque
// module (pure, sans I/O) vit dans une entree unique de MODULES[mode] :
//   { statsInto, risNote, columns, styleSheet, extraSheets, reportSection }
// Des squelettes generiques (buildRIS / buildXLSX / buildReport) consomment ces entrees.
// L'orchestrateur async reste lineaire (calcul stats -> fichiers coeur -> fichiers annexes
// -> methods.json -> retour). Comportement identique a l'ancien node (verifie golden + harness).
const XLSX = require('xlsx');
const PROXY = 'http://host.docker.internal:3456';
const items = $input.all();
// CORPUS_PAR_FICHIER_v1 (2026-08-25) : le corpus arrive par FICHIER, pas par la frontiere.
//
// Le sous-workflow de tri l'ecrit lui-meme et ne rend qu'un chemin, parce que le moteur de
// workflows RECOPIE les elements au passage d'un workflow a l'autre : sur 12 772 articles,
// cette copie faisait passer la memoire de 1,45 a 2,49 Gio et tuait le run.
//
// L'ancien chemin reste actif quand aucun fichier n'est annonce : petits corpus, autres
// modules, et repli du nœud d'ecriture.
// RESTE OUVERT : CETTE RELECTURE NE COMPARE PAS L'EFFECTIF DU FICHIER A CELUI QUE LE PRODUCTEUR
// ANNONCE (declaration, 2026-09-18). « Ecrire Corpus » du tri pose le chemin ET l'effectif dans
// le MEME objet, et il rend les deux a son appelant. « Relire Corpus » de l'orchestrateur compare
// les deux et refuse quand ils different ; ici, la relecture se fait sans aucune comparaison, si
// bien qu'un corpus tronque ou remplace passerait en silence, ce qui est le defaut d'origine.
// Mesure du 2026-09-18 sur les 21 fichiers de workflows, code et commentaires separes par
// l'analyseur syntaxique : la clef d'effectif `_corpus_n` parait 2 fois dans le tri, qui l'ecrit,
// 6 fois dans l'orchestrateur, qui la lit et l'explique, et dans CE fichier 0 fois dans du code,
// sa seule occurrence etant celle de cette declaration. C'est donc une grandeur que ce chemin RECOIT et
// ne lit jamais. Rien n'est change ici : le remede demande sa propre mesure sur un run du module,
// que ce lot n'a pas faite.
let articles;
const _entree = (items[0] && items[0].json) || {};
if (_entree._corpus_fichier) {
  articles = JSON.parse(require('fs').readFileSync(_entree._corpus_fichier, 'utf-8'));
  console.log('Corpus relu depuis ' + _entree._corpus_fichier + ' (' + articles.length + ')');
} else {
  articles = items.map(i => i.json);
}
const mode = (articles[0] && articles[0]._module_mode) || 'unknown';
const outputFolder = (articles[0] && articles[0].output_folder) || '/desktop/ultralab-module-output';
const folderName = (articles[0] && articles[0]._folder_name) || 'ultralab-module-output';

// ===================================================================================
// HELPERS PARTAGES (mode-agnostiques)
// ===================================================================================
//<<<PURE_START>>>
function __pEsc(s){ return String(s == null ? '' : s).replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;'); }
// ACCORD_LIGNE_UNIQUE_v1 (2026-09-20) : LA PASTILLE DU DIAGRAMME SUIT LA MEME REGLE QUE LE
// FICHIER DE METHODES ECRIT PAR CE NOEUD, ET LA REGLE UNIQUE DU DEPOT POUR SON CONTENU.
//
// CE QUI DIVERGEAIT. La pastille gardait ACCORD_PUBLIABLE_v1 (actif, au moins une paire, ET un
// kappa chiffre) quand le transport vers methods.json, l'export du pipeline et le rapport PRISMA
// de la chaine suivent ACCORD_MESURE_v1 (actif et au moins une paire, sans condition sur le
// kappa). Deux ecrivains du MEME bloc, dans le MEME noeud, ne peuvent pas diverger.
//
// LES DEUX REGLES ONT ETE MESUREES SUR LES ETATS REELS DU PRODUCTEUR avant de choisir, la chaine
// entiere jouee (« Ecrire Corpus », « Double Screen Kappa », puis ce noeud) :
//   - 18 paires, deux categories, kappa 0.769 : les deux regles publient ;
//   - 12 paires D'UNE SEULE CATEGORIE, kappa NON DEFINI (null), AC1 = 1, PABAK = 1, accord
//     100 % : ACCORD_MESURE publie, ACCORD_PUBLIABLE NON. La pastille etait donc le SEUL
//     document de ce run a taire une double lecture reellement mesuree, quand methods.json,
//     report.md, l'item 8 de la checklist et le rapport consolide la declaraient tous ;
//   - 1 paire discordante, kappa 0 : les deux publient ;
//   - zero paire mesuree, double relecture activee : les deux se taisent, comme le transport ;
//   - double relecture desactivee : aucun bloc, rien nulle part.
// La regle JUSTE est donc ACCORD_MESURE_v1, celle des lecteurs du moteur
// (run_resume.bloc_double_fulltext_publie) : un accord MESURE se publie, et c'est le kappa qui se
// tait quand il n'est pas defini, pas la double lecture.
//
// ECHANGER LE SEUL PREDICAT NE SUFFISAIT PAS, ET C'EST MESURE AUSSI : sur les 12 paires d'une
// seule categorie, la pastille aurait publie « kappa = null (n/a), 0 desaccords », c'est-a-dire
// exactement le defaut pour lequel ACCORD_PUBLIABLE_v1 avait ete ecrit. Une branche qu'on rend
// atteignable rencontre les sorties degenerees de son producteur : le CONTENU suit donc la regle
// unique du depot (src/consolidated_report.py, `_ligne_accord` et `_portee_de_l_accord`, celle de
// l'item 8 de la checklist) :
//   - LA PORTEE D'ABORD : combien de references (ou de rapports) ont ete jugees par les deux, le
//     denominateur « sur N » quand le bloc porte un premier effectif SUPERIEUR, et la selection
//     restreinte quand elle est declaree ;
//   - LES TROIS INDICES, et UN INDICE QUE LE BLOC NE PORTE PAS EST DIT, jamais tu ;
//   - le taux d'accord observe accole au kappa, meme quand le kappa n'est pas publie ;
//   - les nombres ecrits par la regle unique : `agreement.ecrire_nombre` se declare MIROIR de
//     `String` en JavaScript, donc ici c'est `String` lui-meme, et le zero reste une mesure.
// AUCUNE ETIQUETTE D'INTERPRETATION N'EST IMPRIMEE, comme dans les quatre rapports du relais et
// pour leur raison : les libelles du producteur (« substantial », « almost perfect ») sont
// anglais, et ce document est francais (il s'ouvre par <html lang=\"fr\">). Rien n'est perdu :
// report.md du meme run garde son « (substantial) » a cote de son kappa chiffre.
// LE NOMBRE DE DESACCORDS RESTE PUBLIE : il ne vient pas de la regle du depot, mais la pastille le
// portait deja et aucun autre endroit de ce document ne le donne.
// CE QUI N'EST PAS EPROUVE PAR UN CAS, ET QUI EST ECRIT QUAND MEME : les bornes, le niveau de
// confiance et la selection restreinte. Mesure du 2026-09-20 sur les DEUX producteurs de ce bloc
// (ultralab-screening.json et ultralab-fulltext.json) : 0 occurrence de `*_ci_low`, `*_ci_high`,
// `ci_level`, `ci_note` et `selection`. Aucun etat ne les atteint aujourd'hui, et un cas qui en
// fabriquerait un serait satisfait par son propre decor ; elles sont la pour qu'un bloc qui
// gagnerait ces cles soit publie au lieu d'etre tronque en silence. Le denominateur « sur N »,
// lui, EST atteignable : ultralab-fulltext.json ecrit `n_first_rated`, et un cas l'eprouve.
// La note de methode n'est PAS transcrite : c'est une phrase du producteur, et la phrase entre
// crochets nomme deja le niveau.
function __pNbAccord(v) { return (typeof v === 'number' && isFinite(v)) ? v : null; }
function __pEcrireAccord(v) { return (__pNbAccord(v) === null) ? null : String(v); }
function __pEntierAccord(v) {
  return (typeof v === 'number' && isFinite(v) && Math.floor(v) === v && v >= 0) ? v : null;
}
// `agreement.intervalle_publiable` : la valeur existe, les deux bornes sont des nombres, la haute
// DEPASSE la basse, et les deux vivent dans [-1 ; 1]. Une largeur nulle n'est pas une precision.
function __pBornesAccord(b, cle) {
  if (__pEcrireAccord(b[cle]) === null) return null;
  const basA = __pNbAccord(b[cle + '_ci_low']), hautA = __pNbAccord(b[cle + '_ci_high']);
  if (basA === null || hautA === null || !(hautA > basA) || basA < -1 || hautA > 1) return null;
  return ' [' + String(basA) + ' ; ' + String(hautA) + ']';
}
// `agreement.niveau_publie` : une proportion est ramenee en pour cent AVANT l'arrondi, l'arrondi
// est celui de l'ecran, et la borne ouverte ]0 ; 100[ porte sur le nombre IMPRIME.
function __pNiveauAccord(b) {
  const vA = __pNbAccord(b.ci_level);
  if (vA === null) return null;
  const rA = Math.round(vA > 1 ? vA : 100 * vA);
  return (rA > 0 && rA < 100) ? rA : null;
}
// `_effectif_dit` : le singulier jusqu'a 1, zero compris.
function __pEffectifDit(n, mots) { return n + ' ' + (n <= 1 ? mots[0] : mots[1]); }
// Ce que les deux juges ont juge : les mots de l'item 8, selon la phase.
const __MOTS_REFERENCES = ['référence jugée', 'références jugées'];
const __MOTS_RAPPORTS = ['rapport jugé', 'rapports jugés'];
// `_portee_de_l_accord` : les morceaux de la portee sont joints par une VIRGULE et ne font qu'UN
// segment, comme dans la version du depot.
function __pPorteeAccord(b, mots) {
  const out = [];
  const n2A = __pEntierAccord(b.n_double_rated);
  if (n2A !== null) {
    let tA = __pEffectifDit(n2A, mots) + ' par les deux';
    const n1A = __pEntierAccord(b.n_first_rated);
    if (n1A !== null && n1A > n2A) tA += ' sur ' + n1A;
    out.push(tA);
  }
  const selA = b.selection;
  if (selA && selA !== 'tous') {
    out.push('sélection restreinte (' + __pEsc(b.selection_label_fr || selA)
      + '), l\'accord porte sur cette seule sélection');
  }
  return out.length ? [out.join(', ')] : [];
}
const __INDICES_ACCORD = [['cohen_kappa', 'κ'], ['gwet_ac1', 'AC1'], ['pabak', 'PABAK']];
function __pLigneAccord(b, isFT) {
  const morceaux = __pPorteeAccord(b, isFT ? __MOTS_RAPPORTS : __MOTS_REFERENCES);
  let avecIC = false;
  for (let iA = 0; iA < __INDICES_ACCORD.length; iA++) {
    const cleA = __INDICES_ACCORD[iA][0], nomA = __INDICES_ACCORD[iA][1];
    const valeurA = __pEcrireAccord(b[cleA]);
    let tA;
    if (valeurA === null) {
      tA = '<b>' + nomA + ' non publié</b>';
    } else {
      let teteA = nomA + ' = ' + valeurA;
      const bornesA = __pBornesAccord(b, cleA);
      if (bornesA) { teteA += bornesA; avecIC = true; }
      tA = '<b>' + teteA + '</b>';
    }
    if (cleA === 'cohen_kappa') {
      const tauxA = __pEcrireAccord(b.percent_agreement);
      if (tauxA !== null) tA += ', accord ' + tauxA + '%';
    }
    morceaux.push(tA);
  }
  let ligneA = morceaux.join(' · ');
  if (avecIC) {
    const nvA = __pNiveauAccord(b);
    ligneA += '. Entre crochets : intervalle de confiance'
      + ((nvA !== null) ? (' à ' + nvA + ' %') : '') + '.';
  }
  const dA = __pEntierAccord(b.n_disagree);
  if (dA !== null) ligneA += ' · ' + dA + (dA <= 1 ? ' désaccord' : ' désaccords');
  return ligneA;
}
// ACCORD_MESURE_v1 (2026-09-12) : le TRANSPORT vers methods.json suit la regle des lecteurs du
