// Hardening XLSX : tronque cellules a 32700 chars + retire chars de controle (partage)
function safeCell(v) {
  if (v === null || v === undefined) return '';
  if (typeof v === 'number' || typeof v === 'boolean') return v;
  let s = (typeof v === 'string') ? v : (typeof v === 'object' ? JSON.stringify(v) : String(v));
  // Retire caracteres de controle (sauf tab, LF, CR)
  s = s.replace(/[\x00-\x08\x0B\x0C\x0E-\x1F\x7F]/g, ' ');
  if (/^[=@\t\r]/.test(s)) s = "'" + s;  // LOT_S_SANITIZE_v2 anti-formule (=/@ seulement, pas les nombres +/-)
  if (s.length > 32700) {
    // MARQUE BILINGUE (2026-10-17, etape E10, tour 2) : elle n'etait qu'en francais, sans
    // accents. Meme marque que src/export_extraction.py (`MARQUE_TRONQUEE`), que la route
    // regeneree ecrit ; 32 700 caracteres plus la marque tiennent dans une cellule (32 767).
    s = s.substring(0, 32700) + ' [tronqué à 32\u00a0700 caractères / truncated at 32,700 characters]';
  }
  return s;
}

// === ECRIRE LES FICHIERS : EN DIRECT, LE PROXY EN REPLI ===
//
// ECRITURE_DIRECTE_v1 (2026-08-25). CE QUI A IMPOSE CE CHANGEMENT :
//
//     FATAL ERROR: Reached heap limit Allocation failed - JavaScript heap out of memory
//
// L'assemblage d'un corpus de 12 772 references ne tenait pas dans la memoire disponible.
// Chaque fichier etait construit en memoire PUIS recopie dans le corps d'une requete, qui le
// re-serialisait en JSON. Pour le corpus seul : 49 Mo de texte plus une cinquantaine de
// mega-octets de corps de requete, en plus des 12 772 articles deja en memoire.
//
// Essaye a 2 048 puis a 2 560 Mo de tas : la meme erreur. La machine n'offre que 3,94 Go a la
// machine virtuelle. Il n'y a pas de plafond a monter, il faut cesser de tenir deux copies.
//
// LA GARDE DE CHEMIN DEMENAGE AVEC L'ECRITURE. C'est le proxy qui confinait les ecritures ;
// en ecrivant directement, ce nœud doit porter la meme regle, et il la porte AVANT d'ecrire.
// Une regle de securite qu'on deplace sans la reposer est une regle qu'on supprime.
function cheminAutorise(p) {
  const s = String(p || '');
  if (s.indexOf('..') >= 0) return false;
  return s.indexOf('/desktop/') === 0 || s.indexOf('/projets/') === 0;
}

async function saveFile(savePath, content, isBase64) {
  if (!cheminAutorise(savePath)) {
    console.log('Ecriture REFUSEE, chemin hors des racines autorisees : ' + savePath);
    return false;
  }
  // 1) EN DIRECT. Le dossier de sortie est monte dans le conteneur ; on evite ainsi la
  //    seconde serialisation, qui doublait le pic de memoire par fichier.
  try {
    const _fs = require('fs');
    const _path = require('path');
    _fs.mkdirSync(_path.dirname(savePath), { recursive: true });
    if (isBase64) {
      _fs.writeFileSync(savePath, Buffer.from(content, 'base64'));
    } else {
      _fs.writeFileSync(savePath, content, 'utf-8');
    }
    return true;
  } catch (e) {
    console.log('Ecriture directe impossible (' + e.message + '), repli sur le proxy');
  }
  // 2) LE PROXY EN REPLI. Plus couteux en memoire, mais une ecriture qui echoue vaut mieux
  //    qu'un fichier perdu : c'est exactement ce qu'on cherche a ne plus produire.
  try {
    const body = isBase64 ? { save_to: savePath, content_base64: content } : { save_to: savePath, content };
    const resp = await this.helpers.httpRequest({
      method: 'POST',
      url: PROXY + '/save',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify(body),
      timeout: 60000
    });
    return resp && resp.success;
  } catch (e) {
    console.log('Save error: ' + e.message);
    return false;
  }
}

