// Format BibTeX/LaTeX (.bib) pour les articles
function buildBibTeX(articles) {
  function escapeBib(s) {
    if (!s) return '';
    return String(s)
      .replace(/\\/g, '\\textbackslash{}')
      .replace(/[{}]/g, '')  // pas d'accolades dans les valeurs
      .replace(/[#$%&_]/g, '\\$&')  // chars speciaux LaTeX
      .replace(/[\r\n]+/g, ' ')
      .trim();
  }
  function makeKey(a, i) {
    // cle = 1er auteur (surname) + annee + index (anti-doublon)
    let surname = '';
    if (Array.isArray(a.authors) && a.authors.length > 0) {
      const parts = String(a.authors[0]).trim().split(/\s+/);
      surname = (parts[parts.length - 1] || '').replace(/[^a-zA-Z]/g, '');
    }
    const year = (a.year || 'NA').toString().match(/\d{4}/);
    return (surname || 'anon') + (year ? year[0] : 'NA') + '_' + (i + 1);
  }
  return articles.map((a, i) => {
    const key = makeKey(a, i);
    const authors = Array.isArray(a.authors) ? a.authors.map(escapeBib).join(' and ') : escapeBib(a.authors || '');
    let entry = '@article{' + key + ',\n';
    if (a.title) entry += '  title = {' + escapeBib(a.title) + '},\n';
    if (authors) entry += '  author = {' + authors + '},\n';
    if (a.journal) entry += '  journal = {' + escapeBib(a.journal) + '},\n';
    if (a.year) entry += '  year = {' + escapeBib(a.year) + '},\n';
    if (a.volume) entry += '  volume = {' + escapeBib(a.volume) + '},\n';
    if (a.issue) entry += '  number = {' + escapeBib(a.issue) + '},\n';
    if (a.pages) entry += '  pages = {' + escapeBib(a.pages).replace('-', '--') + '},\n';
    if (a.doi) entry += '  doi = {' + escapeBib(a.doi) + '},\n';
    if (a.url) entry += '  url = {' + escapeBib(a.url) + '},\n';
    if (a.abstract) entry += '  abstract = {' + escapeBib(a.abstract) + '},\n';
    if (a.pmid) entry += '  pmid = {' + escapeBib(a.pmid) + '},\n';
    entry += '}\n\n';
    return entry;
  }).join('');
}

// VALEUR_EXTRAITE_ECRITE_v1 (2026-10-17, etape E10 de la conception « extraction »). Une valeur
// extraite s'ecrit dans les exports par UNE regle, celle de src/export_extraction.py
// (`valeur_ecrite`), dont les cas (`CAS_VALEURS`) sont rejoues contre cette fonction par
// tests/test_extraction_exports_et_journal.py. CE QUI ETAIT FAUX, mesure le 2026-10-17 par ce
// noeud : une valeur absente s'ecrivait « null » dans la feuille de resultats et dans le rapport
// (`String(null)`), et un zero disparaissait des notes du RIS (`String(v || '')`). L'absence ne
// s'ecrit pas ; un zero reste « 0 » ; une liste ou un objet s'ecrit en JSON compact. Un nombre ou
// un booleen lu dans un corpus JSON s'ecrit par JSON.stringify comme par String() (un nombre non
// fini n'y existe pas).
function __ulValeurExport(v) {
  if (v === null || v === undefined) return '';
  if (typeof v === 'string') return v;
  try { const s = JSON.stringify(v); return (s === undefined) ? String(v) : s; } catch (e) { return String(v); }
}

// PROVENANCE_EXPORTEE_v1 (2026-10-17, etape E10, brique 9 de la conception). La feuille
// « Provenance » du classeur d'un run d'extraction : une ligne par article et par champ, avec la
// citation, la page, l'origine, le statut de verification calcule par le code, la coherence,
// l'accord des deux extractions, le drapeau « a relire », la relecture humaine et le texte lu.
// AUCUN EXPORT NE LE DISAIT. MEME REGLE que src/export_extraction.py (`lignes_provenance`), qui
// ecrit la meme feuille dans l'export regenere apres la relecture (/api/run/regenerate) ; un cas
// de test compare les deux sur les memes articles. Les libelles sont ceux de ce module.
// « RELU PAR UN HUMAIN » VAUT « non » A L'ASSEMBLAGE. Une validation par champ ne compte que dans
// le run ou elle a ete faite (`run` egal a l'identite de son dossier,
// `export_extraction.validations_du_run`) : ce run s'ecrit en ce moment, aucune ne peut lui
// appartenir, et une validation recopiee d'un run precedent decrit d'autres valeurs. Le badge d'une
// forme ancienne ne vaut, dans un run d'extraction, qu'avec la trace d'une correction faite dans ce
// run (`index_taches.chiffres_verifies`, regle 4), et « Filter & Prepare » le retire a l'entree.
// L'export regenere relit la regle entiere.
const __UL_OUI = 'oui / yes', __UL_NON = 'non / no';
const __UL_ORIGINE = { texte: ['texte', 'text'], tableau: ['tableau', 'table'], figure: ['figure', 'figure'] };
const __UL_VERIF = { exacte: ['exacte', 'exact'], autre_page: ['autre page', 'other page'],
