  saisie_humaine: ['saisie par le relecteur, non vérifiée', 'entered by the reviewer, not checked'],
  sans_citation: ['sans citation', 'no quote'] };
// Les controles de coherence (src/coherence_extraction.py), dont la provenance garde les codes :
// un nom court par code, en francais et en anglais (tour 2, 2026-10-17 : « coh_ic_hors » s'ecrivait
// tel quel). Meme table que src/export_extraction.py (`LIBELLES_COHERENCE`).
const __UL_COHERENCE = {
  coh_somme_bras: ['effectifs des bras supérieurs au total', 'arm sizes exceed the total'],
  coh_evenements_effectif: ['événements supérieurs à l\'effectif', 'events exceed the arm size'],
  coh_pourcentage: ['pourcentage incohérent', 'inconsistent percentage'],
  coh_bornes_inversees: ['bornes de l\'intervalle inversées', 'interval bounds out of order'],
  coh_ic_hors: ['estimation hors de son intervalle', 'estimate outside its interval'],
  coh_ic_traverse_zero: ['intervalle qui traverse zéro à tort', 'interval wrongly crossing zero'],
  coh_rapport_non_positif: ['rapport non strictement positif', 'ratio not strictly positive'],
  coh_signe: ['signe contraire à la citation', 'sign contradicting the quote'],
  coh_sd_se: ['écart-type et erreur-type confondus', 'standard deviation and standard error confused'],
  coh_mediane_iqr: ['médiane ou étendue au lieu d\'une moyenne ou d\'un écart-type',
