  coh_p_hors: ['valeur de p hors de [0 ; 1]', 'p value outside [0; 1]'],
  coh_bras_multiples: ['étude à plus de deux bras', 'study with more than two arms'] };
const __UL_ACCORD = { concordant: ['concordant', 'agreeing'], discordant: ['discordant', 'disagreeing'],
  non_evaluable: ['non évaluable', 'not assessable'] };
const __UL_LECTURE = { complet: ['texte intégral, page par page', 'full text, page by page'],
  passages: ['passages choisis par champ', 'passages selected per field'],
  resume: ['résumé seul', 'abstract only'],
  debut_du_texte: ['12 000 premiers caractères du texte, sans page', 'first 12,000 characters of the text, no page'] };
const __UL_ENTETES_PROVENANCE = ['Titre / Title', 'DOI', 'Champ / Field', 'Valeur / Value', 'Unité / Unit',
  'Citation / Quote', 'Page', 'Origine / Origin', 'Vérification / Check', 'Cohérence / Consistency',
  'Accord / Agreement', 'À relire / To review', 'Relu par un humain / Human-reviewed',
  'Validée par / Validated by', 'Mode de lecture / Reading mode'];
function __ulObjet(x) { return !!x && typeof x === 'object' && !Array.isArray(x); }
function __ulLibelle(table, code) {
  if (code === null || code === undefined || code === '') return '';
