}
function __ulModeLecture(a) {
  const source = (typeof a._extract_source === 'string') ? a._extract_source : '';
  if (source.indexOf('abstract') === 0) return 'resume';
  const m = __ulObjet(a._lecture_extraction) ? a._lecture_extraction.mode : null;
  if (typeof m === 'string' && m) return m;
