function __ulPage(p) { return (typeof p === 'number' && Number.isInteger(p)) ? p : ''; }
function __ulLignesProvenance(articles) {
  const rows = [];
  (articles || []).forEach(function (a) {
    if (!__ulObjet(a) || !__ulObjet(a._extracted)) return;
    // Un article hors du perimetre de l'extraction (voie v2) n'a pas ete extrait par CE run : sa
    // provenance, celle d'un run precedent, n'est pas ecrite (2026-10-17, etape E6 ; meme regle
    // que src/export_extraction.py, `lignes_provenance`).
    if (a.extraction_perimetre === 'hors') return;
    const prov = __ulObjet(a._extracted_prov) ? a._extracted_prov : {};
    const relire = Array.isArray(a._extraction_a_relire) ? a._extraction_a_relire : [];
    const lecture = __ulLibelle(__UL_LECTURE, __ulModeLecture(a));
    Object.keys(a._extracted).forEach(function (champ) {
      const p = __ulObjet(prov[champ]) ? prov[champ] : {};
      const coh = Array.isArray(p.coherence) ? p.coherence : [];
      rows.push([__ulValeurExport(a.title || ''), __ulValeurExport(a.doi || ''), champ,
        __ulValeurExport(a._extracted[champ]), __ulValeurExport(p.unite), __ulValeurExport(p.citation),
        __ulPage(p.page), __ulLibelle(__UL_ORIGINE, p.origine), __ulLibelle(__UL_VERIF, p.verif),
        coh.map(function (c) { return __ulLibelle(__UL_COHERENCE, c); }).join(', '),
        __ulLibelle(__UL_ACCORD, __ulAccordDuChamp(a, champ)),
        (relire.indexOf(champ) >= 0) ? __UL_OUI : '', __UL_NON, '', lecture]);
    });
