      // exclusion prononcee sur un resume complet.
      const __ts = articles.filter(a => a._juge_sur_titre_seul);
      stats.titre_seul = __ts.length;
      stats.titre_seul_exclus = __ts.filter(a => a.screening_decision === 'Exclude').length;
