        const MAX = 15;
        const montres = themes.slice(0, MAX);
        const reste = themes.slice(MAX);
        const resteN = reste.reduce(function (s, t) { return s + t.n; }, 0);

        const total = arts.length || 1;
        const plusGros = montres[0].n || 1;
        const W = 860, LEFT = 300, PLOT = 430, ROW = 26, TOP = 64;
        const lignes = montres.length + (reste.length ? 1 : 0) + (nonClasses ? 1 : 0);
        const H = TOP + lignes * ROW + 40;
        const o = [];
        o.push('<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 ' + W + ' ' + H + '" '
          + 'width="' + W + '" height="' + H + '" font-family="system-ui,sans-serif">');
        o.push('<rect width="' + W + '" height="' + H + '" fill="#fff"/>');
        o.push('<text x="20" y="30" font-size="17" font-weight="600">Repartition des articles '
          + 'par theme</text>');
        o.push('<text x="20" y="50" font-size="12" fill="#666">' + arts.length
          + ' articles, ' + themes.length + ' theme(s)'
          + (nonClasses ? (', ' + nonClasses + ' non classe(s)') : '') + '</text>');

        function barre(y, libelle, n, couleur) {
          const large = Math.max(2, Math.round((n / plusGros) * PLOT));
          const pct = Math.round((n / total) * 1000) / 10;
          const court = libelle.length > 40 ? (libelle.substring(0, 39) + '\u2026') : libelle;
          o.push('<text x="' + (LEFT - 10) + '" y="' + (y + 13) + '" font-size="12" '
            + 'text-anchor="end" fill="#222">' + __pEsc(court) + '</text>');
          o.push('<rect x="' + LEFT + '" y="' + (y + 3) + '" width="' + large + '" height="14" '
            + 'rx="3" fill="' + couleur + '"/>');
          o.push('<text x="' + (LEFT + large + 8) + '" y="' + (y + 14) + '" font-size="11" '
            + 'fill="#444">' + n + ' (' + pct + ' %)</text>');
        }

        let y = TOP;
        for (const t of montres) { barre(y, t.l, t.n, '#4472C4'); y += ROW; }
        if (reste.length) {
          barre(y, reste.length + ' theme(s) plus petits', resteN, '#8FAADC'); y += ROW;
        }
        if (nonClasses) {
          // En gris, et nomme : un lot de traitement en echec n'est pas un theme.
          barre(y, 'Non classes (lot en echec)', nonClasses, '#B0B0B0'); y += ROW;
        }
        o.push('</svg>');

        carteOk = await ctx.saveFile.call(this, ctx.outputFolder + '/cluster-map.html',
