    columns(articles) {
      // TRI PAR TAILLE puis alphabetique : l'ordre alphabetique seul mettait un theme de
      // deux articles avant celui qui en porte deux cents.
      const tailles = {};
      for (const a of articles) {
        const c = a.cluster_label || 'Unclustered';
        tailles[c] = (tailles[c] || 0) + 1;
      }
      const headers = ['Thème', 'Taille du thème', 'Titre', 'Auteurs', 'Année', 'Journal',
        'DOI', 'Abstract'];
      const sorted = [...articles].sort(function (a, b) {
        const ca = a.cluster_label || 'Unclustered', cb = b.cluster_label || 'Unclustered';
        const d = (tailles[cb] || 0) - (tailles[ca] || 0);
        return d !== 0 ? d : ca.localeCompare(cb);
      });
      const rows = sorted.map(a => [a.cluster_label||'Unclustered',
        tailles[a.cluster_label || 'Unclustered'] || 0, a.title||'', (a.authors||[]).join('; '), a.year||'', a.journal||'', a.doi||'', (a.abstract||'').substring(0,1000)]);
      return { headers, rows };
    },
    reportSection(articles, stats, a0) {
      let r = '';
      const byCluster = {};
      articles.forEach(a => { const c = a.cluster_label || 'Unclustered'; (byCluster[c] = byCluster[c] || []).push(a); });
      const total = articles.length || 1;
      // MOTS DISTINCTIFS : sur-representation dans le theme par rapport au corpus, et non
      // frequence brute, qui rendrait les memes mots pour tous les themes.
      const VIDES = new Set(['the','and','for','with','that','this','from','were','was','are',
        'have','has','been','their','which','study','studies','patients','results','among',
        'between','using','based','data','analysis','review','effect','effects','les','des',
        'une','dans','pour','sur','par','aux','avec','plus','etude','etudes']);
      function mots(liste) {
        const f = {};
        for (const a of liste) {
          const vus = new Set(String(a.title || '').toLowerCase()
            .replace(/[^a-z\u00e0-\u00ff]+/g, ' ').split(' ')
            .filter(function (m) { return m.length > 3 && !VIDES.has(m); }));
          for (const m of vus) f[m] = (f[m] || 0) + 1;
        }
        return f;
      }
      const fCorpus = mots(articles);
      const ordre = Object.keys(byCluster)
        .sort(function (x, y) { return byCluster[y].length - byCluster[x].length; });
      // LA FUSION DES ETIQUETTES, DITE AU RAPPORT (FUSION_DITE_v1, 2026-10-19) : en francais puis
      // en anglais, a partir des statistiques que publie le bloc des statistiques de ce module.
      // Un dossier sans statut (ecrit avant ce lot) n'a pas de paragraphe.
      // Second tour du 2026-10-19, apres verification : « non_tentee » cite la limite FIXEE de 500
      // etiquettes (il disait « plus qu'un seul appel au modele ne peut lire », ce que le calcul du
      // nœud de fusion contredit) ; « faite » et « partielle » disent « rattachees a un theme » (une
      // etiquette peut rester seule dans son theme) ; « echec_arret » reste juste quand le run est
      // arrete pendant les lots, sans etiquette ; « sans_lot » et « sans_etiquette » remplacent
      // « non_requise » la ou il etait faux (moins de trois articles ; aucune etiquette rendue).
      // La valeur 500 est celle de MAX_ETIQUETTES_FUSION (workflows/ultralab-clustering.json, nœud
      // « Expand Results », et src/server.py) : tests/test_regroupement_fusion_dite.py les compare.
      if (stats && stats.fusion_themes) {
        const FUSION_DITE = {
          faite: ["La fusion des étiquettes a été faite : chacune des {avant} étiquettes écrites lot par lot est rattachée à l'un des {apres} thèmes ({vises} visés).",
                  "The label merge was done: each of the {avant} labels written batch by batch is assigned to one of {apres} themes ({vises} targeted)."],
          partielle: ["La fusion des étiquettes n'est que partielle : {rattachees} étiquettes sur {avant} sont rattachées à un thème, les autres sont gardées telles quelles ({apres} thèmes, {vises} visés).",
                      "The label merge is only partial: {rattachees} of {avant} labels are assigned to a theme, the others are kept as they were ({apres} themes, {vises} targeted)."],
          sans_effet: ["La fusion des étiquettes est restée sans effet : la réponse du modèle laisse chaque étiquette seule dans son thème. Les {avant} étiquettes écrites lot par lot sont gardées ({vises} thèmes visés).",
                       "The label merge had no effect: the model's answer leaves every label alone in its theme. The {avant} labels written batch by batch are kept ({vises} themes targeted)."],
          echec_arret: ["La fusion des étiquettes n'a pas eu lieu : le run a été arrêté avant elle. Les étiquettes écrites lot par lot avant l'arrêt sont gardées telles quelles : {avant} étiquettes, {vises} thèmes visés.",
                        "The label merge did not take place: the run was stopped before it. The labels written batch by batch before the stop are kept as they were: {avant} labels, {vises} themes targeted."],
          echec_appel: ["La fusion des étiquettes a échoué : l'appel au modèle n'a rendu aucune réponse. Les {avant} étiquettes écrites lot par lot sont gardées telles quelles ({vises} thèmes visés).",
                        "The label merge failed: the model call returned no answer. The {avant} labels written batch by batch are kept as they were ({vises} themes targeted)."],
          echec_coupee: ["La fusion des étiquettes a échoué : la réponse du modèle a été coupée par la limite de longueur. Les {avant} étiquettes écrites lot par lot sont gardées telles quelles ({vises} thèmes visés).",
                         "The label merge failed: the model's answer was cut off by the length limit. The {avant} labels written batch by batch are kept as they were ({vises} themes targeted)."],
          echec_illisible: ["La fusion des étiquettes a échoué : la réponse du modèle est illisible ou n'a pas la forme demandée. Les {avant} étiquettes écrites lot par lot sont gardées telles quelles ({vises} thèmes visés).",
                            "The label merge failed: the model's answer is unreadable or does not have the requested form. The {avant} labels written batch by batch are kept as they were ({vises} themes targeted)."],
          echec_vide: ["La fusion des étiquettes a échoué : la réponse du modèle ne rattache aucune étiquette à un thème. Les {avant} étiquettes écrites lot par lot sont gardées telles quelles ({vises} thèmes visés).",
                       "The label merge failed: the model's answer assigns no label to a theme. The {avant} labels written batch by batch are kept as they were ({vises} themes targeted)."],
          non_requise: ["La fusion des étiquettes n'a pas été nécessaire : les lots ont rendu {apres} thème(s), pas plus que les {vises} visés.",
                        "The label merge was not needed: the batches returned {apres} theme(s), no more than the {vises} targeted."],
          non_tentee: ["La fusion des étiquettes n'a pas été tentée : {avant} étiquettes, au-delà de la limite de 500 fixée pour un seul appel de fusion. Elles sont gardées telles quelles ({vises} thèmes visés).",
                       "The label merge was not attempted: {avant} labels, beyond the limit of 500 set for a single merge call. They are kept as they were ({vises} themes targeted)."],
          sans_lot: ["La fusion des étiquettes n'a pas lieu d'être : avec moins de trois articles, aucun lot n'est formé et les articles forment un seul thème.",
                     "The label merge does not apply: with fewer than three articles, no batch is formed and the articles form a single theme."],
          sans_etiquette: ["La fusion des étiquettes n'a pas eu lieu : aucun lot n'a rendu d'étiquette, il n'y avait rien à fusionner. Les articles restent non classés.",
                           "The label merge did not take place: no batch returned a label, so there was nothing to merge. The articles remain unclustered."],
        };
        const nb = function (v) { return (typeof v === 'number') ? String(v) : '?'; };
        const vals = { avant: nb(stats.etiquettes_avant_fusion), apres: nb(stats.clusters),
          vises: nb(stats.themes_vises), rattachees: nb(stats.etiquettes_rattachees),
          statut: String(stats.fusion_themes) };
        const dit = Object.prototype.hasOwnProperty.call(FUSION_DITE, stats.fusion_themes)
          ? FUSION_DITE[stats.fusion_themes]
          : ["Statut de la fusion des étiquettes : {statut}.", "Label merge status: {statut}."];
        const remplir = function (s) {
          return s.replace(/\{(\w+)\}/g, function (_m, k) { return vals[k]; }); };
        // P22 (2026-10-20) : UNE FUSION FAITE LOIN DU NOMBRE VISE EST SIGNALEE. « faite » vaut des que
        // chaque etiquette est rattachee et que le nombre de themes baisse, d'une unite comprise : 49
        // themes pour 11 vises passaient pour un resultat ordinaire. Au-dela du double du nombre vise,
        // le paragraphe le dit (meme regle a l'ecran : app/src/lib/fusionThemes.ts, `loinDuVise`).
        const loin = stats.fusion_themes === 'faite' && typeof stats.clusters === 'number'
          && typeof stats.themes_vises === 'number' && stats.clusters > 2 * stats.themes_vises;
        const LOIN = [' Avertissement : la fusion laisse {apres} thèmes pour {vises} visés, plus du double. Relisez les thèmes avant de les publier.',
          ' Warning: the merge leaves {apres} themes for {vises} targeted, more than twice as many. Review the themes before publishing them.'];
        r += '### Fusion des étiquettes / Label merge\n\n' + remplir(dit[0] + (loin ? LOIN[0] : '')) + '\n\n'
          + remplir(dit[1] + (loin ? LOIN[1] : '')) + '\n\n';
      }
      r += '### Themes identifies\n\n';
      r += '| Theme | Articles | Part | Annees | Revue la plus frequente | Mots distinctifs |\n';
      r += '|---|---|---|---|---|---|\n';
      for (const c of ordre) {
        const lot = byCluster[c];
        const pct = Math.round((lot.length / total) * 1000) / 10;
        const annees = lot.map(function (a) { return parseInt(a.year, 10); })
          .filter(function (y) { return y > 1800 && y < 2200; }).sort();
        // LA PERIODE PAR UN TRAIT D'UNION (2026-10-24, regle de l'auteur : aucun tiret
        // demi-cadratin dans un document produit).
        const periode = annees.length
          ? (annees[0] === annees[annees.length - 1]
              ? String(annees[0]) : (annees[0] + '-' + annees[annees.length - 1]))
          : 'n. d.';
        const revues = {};
        for (const a of lot) { const j = (a.journal || '').trim(); if (j) revues[j] = (revues[j] || 0) + 1; }
        const rev = Object.keys(revues).sort(function (x, y) { return revues[y] - revues[x]; })[0];
        const fLot = mots(lot);
        const distinctifs = Object.keys(fLot)
          .filter(function (m) { return fLot[m] >= 2; })
          .map(function (m) {
            const part = fLot[m] / lot.length;
            const global = (fCorpus[m] || fLot[m]) / total;
            return { m: m, s: part / (global || 1) };
          })
          .sort(function (x, y) { return y.s - x.s; })
          .slice(0, 5).map(function (x) { return x.m; });
        r += '| ' + c + ' | ' + lot.length + ' | ' + pct + ' % | ' + periode + ' | '
          + (rev ? (rev.substring(0, 40) + (revues[rev] > 1 ? (' (' + revues[rev] + ')') : ''))
                 : 'n. d.')
          + ' | ' + (distinctifs.join(', ') || 'n. d.') + ' |\n';
      }
      if (stats && stats.unclustered) {
        r += '\n' + stats.unclustered + ' article(s) n\'ont pas pu etre classes '
          + '(lot de traitement en echec). Ils ne figurent dans aucun theme.\n';
      }
      return r;
    },
  },

  'pdf-fetch': {
    // LA PROVENANCE D'UN PDF DITE PAR SA FONCTION (2026-10-20). Ce qui etait faux : le rapport et
    // le classeur de ce module recopiaient `pdf_source` tel quel, et un PDF pris dans la
    // bibliotheque de references de l'utilisateur s'y disait par le nom du logiciel tiers (MESURE
    // sur la base e332a31 : « 1. Essai [zotero] »). La valeur interne reste (« Fetch PDF URLs » la
    // lit, et la clef `by_source` des statistiques aussi) ; le texte montre dit la fonction, en
    // francais et en anglais. Les autres provenances restent ecrites telles quelles. Methode du
    // bloc, appelee par `this` : des cas jouent ce bloc seul.
    sourceLisible(s) {
      return String(s || '').toLowerCase() === 'zotero'
        ? 'votre gestionnaire de références / your reference manager' : (s || '');
    },
    // LA REPARTITION PAR PROVENANCE DES STATISTIQUES (2026-10-20, verification du tour 1 du lot). Ce
    // qui etait faux : `buildReport` et `buildXLSX` ecrivent chaque statistique telle quelle, et cet
    // objet sortait « [object Object] » dans la section « Statistiques » du rapport (MESURE par le
    // vrai nœud), un objet dans la feuille du classeur. Il s'ecrit desormais provenance par
    // provenance, chacune par le libelle des textes montres (`sourceLisible`) ; la clef interne des
    // statistiques reste. Lue par la boucle de ces deux fonctions.
    statLisible(k, v) {
      if (k !== 'by_source' || !v || typeof v !== 'object') return v;
      const noms = { other: 'autre / other', none: 'sans PDF / no PDF' };
      return Object.keys(v).map(s => (noms[s] || this.sourceLisible(s)) + ' : ' + v[s]).join(', ');
    },
    statsInto(stats, articles) {
      stats.downloaded = articles.filter(a => a.pdf_local).length;
      stats.failed = articles.filter(a => a.pdf_url && !a.pdf_local).length;
      stats.no_doi = articles.filter(a => !a.doi).length;
      // PDF_COVERAGE_v1 : clarifier la couverture (exclus non tentes vs tentes)
      stats.total = articles.length;
      stats.attempted = articles.filter(a => a.screening_decision === 'Include' || a.screening_decision === 'Maybe').length;
      stats.excluded_not_fetched = articles.filter(a => a.screening_decision === 'Exclude').length;
      stats.not_downloaded = Math.max(0, stats.attempted - stats.downloaded);
      // PDF_BY_SOURCE_v1 - repartition par source pour affichage UI
      stats.by_source = { zotero: 0, unpaywall: 0, core: 0, europepmc: 0, other: 0, none: 0 };
      for (const a of articles) {
        if (!a.pdf_local) {
          stats.by_source.none++;
          continue;
        }
        const src = (a.pdf_source || '').toLowerCase();
        if (src === 'zotero') stats.by_source.zotero++;
        else if (src === 'unpaywall') stats.by_source.unpaywall++;
        else if (src === 'core' || src === 'core.ac.uk') stats.by_source.core++;
        else if (src.indexOf('europe') === 0 || src === 'europepmc') stats.by_source.europepmc++;
        else stats.by_source.other++;
      }
    },
    columns(articles) {
      const headers = ['Titre', 'Auteurs', 'Année', 'DOI', 'PDF téléchargé', 'Source PDF', 'Chemin local', 'URL'];
      const rows = articles.map(a => [a.title||'', (a.authors||[]).join('; '), a.year||'', a.doi||'', a.pdf_local ? 'Oui' : 'Non', this.sourceLisible(a.pdf_source), a.pdf_local||'', a.pdf_url||a.url||'']);
      return { headers, rows };
    },
    reportSection(articles, stats, a0) {
      let r = '';
      const ok = articles.filter(a => a.pdf_local).slice(0, 10);
      const ko = articles.filter(a => !a.pdf_local && !!a.doi).slice(0, 10);
      r += '### Top 10 PDFs telecharges\n\n';
      ok.forEach((a, i) => { r += (i+1) + '. ' + (a.title || '?').substring(0, 100) + ' [' + this.sourceLisible(a.pdf_source) + ']\n'; });
      r += '\n### Top 10 echecs (DOI sans PDF)\n\n';
      ko.forEach((a, i) => { r += (i+1) + '. ' + (a.title || '?').substring(0, 100) + ' - DOI : ' + a.doi + (a._pdf_motif ? ' [' + a._pdf_motif + ']' : '') + '\n'; });
      // LES ARTICLES SANS PDF, PAR CAUSE (CASCADE_PDF_v1, 2026-10-13) : la cause du dernier echec
      // pertinent que pose le noeud « Fetch PDF URLs » (workflows/ultralab-pdf-fetch.json), dans
      // ses deux langues, puis chaque essai rate (`_pdf_essais`, « source:motif »).
      // LE DETAIL TECHNIQUE DE CHAQUE CAUSE (`_pdf_detail`, CASCADE_PDF_v2, 2026-10-14), trois au
      // plus par cause, les plus frequents, et le compte des autres : plusieurs textes de cause
      // disent « le detail technique l'accompagne », et il n'atteignait pas ce rapport.
      // UNE CAUSE EST UNE CLEF ET SES DEUX TEXTES (CASCADE_PDF_v3, 2026-10-14) : le relais et la route de
      // l'editeur emploient quatre clefs communes aux textes differents (releve du 2026-10-14 sur
      // proxy.MOTIFS_TELECHARGEMENT et publisher_fetch.MOTIFS) ; comptees par clef seule, deux
      // causes etaient publiees sous le texte d'un seul article. Le noeud pose toujours les deux
      // textes avec la clef (`essai` et `doi_absent`) : la garde qui taisait une cause sans texte
      // ne gardait rien et elle est retiree.
      const causes = {}, essais = {};
      articles.filter(a => !a.pdf_local && a._pdf_motif).forEach(a => {
        const k = JSON.stringify([a._pdf_motif, a._pdf_motif_fr, a._pdf_motif_en]);
        const c = causes[k] = causes[k] || { motif: a._pdf_motif, fr: a._pdf_motif_fr, en: a._pdf_motif_en, n: 0, details: {} };
        c.n++;
        if (a._pdf_detail) c.details[a._pdf_detail] = (c.details[a._pdf_detail] || 0) + 1;
        String(a._pdf_essais || '').split(', ').filter(Boolean).forEach(e => { essais[e] = (essais[e] || 0) + 1; });
      });
      const ordreCauses = Object.keys(causes).map(k => causes[k]).sort((x, y) => y.n - x.n);
      if (ordreCauses.length) {
        r += '\n### Sans PDF, par cause / without a PDF, by cause\n\n';
        ordreCauses.forEach(c => {
          r += '- **' + c.motif + '** : ' + c.n + ' article(s)\n';
          r += '  - FR : ' + c.fr + '\n';
          r += '  - EN : ' + c.en + '\n';
          const dm = c.details;
          const ordreDetails = Object.keys(dm).sort((x, y) => dm[y] - dm[x]);
          ordreDetails.slice(0, 3).forEach(d => { r += '  - detail technique / technical detail (' + dm[d] + ') : ' + d + '\n'; });
          if (ordreDetails.length > 3) r += '  - ' + (ordreDetails.length - 3) + ' autre(s) detail(s) / other detail(s)\n';
        });
        const ordreEssais = Object.keys(essais).sort((x, y) => essais[y] - essais[x]);
        if (ordreEssais.length) {
          r += '\n#### Essais rates, source par source / failed attempts, source by source\n\n';
          ordreEssais.forEach(k => { r += '- ' + k + ' : ' + essais[k] + '\n'; });
        }
      }
      return r;
    },
  },

