const timestamp = now.getFullYear() + pad(now.getMonth()+1) + pad(now.getDate()) + '-' + pad(now.getHours()) + pad(now.getMinutes());

// RUN_UID_v1 : deux runs du MEME mode lances dans la MEME minute ecrasaient le meme dossier
// (multi-run, double clic). On ajoute l'identifiant d'execution n8n, qui est le SEUL suffixe
// utilisable ici : « Prepare Articles » et « Build Async Response » calculent ce nom chacun de
// leur cote (branches paralleles) et doivent tomber sur le MEME resultat ; un suffixe aleatoire
// les ferait diverger et le client ne retrouverait plus son dossier. Si l'identifiant n'est pas
// disponible, on retombe sur l'ancien nom (pas de suffixe) plutot que sur une valeur divergente.
let _execId = '';
try { _execId = String(($execution && $execution.id) || ''); } catch (e) { _execId = ''; }
_execId = _execId.replace(/[^A-Za-z0-9]/g, '').slice(0, 12);
const runSuffix = _execId ? ('-e' + _execId) : '';
// Le dossier de sortie choisi par l'utilisateur (mode projet) doit etre respecte ICI aussi :
// « Prepare Articles » l'honore deja, et les deux branches doivent tomber sur le MEME
// dossier, sinon le client et le registre de runs cherchent le resultat au mauvais endroit.
const _uof = (body.output_folder && typeof body.output_folder === 'string') ? body.output_folder.trim().replace(/\/+$/, '') : '';
const _racineOk = (s) => s.indexOf('/desktop') === 0 || s.indexOf('/projets/') === 0;
const _base = (_uof && _racineOk(_uof)) ? _uof : '/desktop';
const expectedFolder = _base + '/ultralab-module-' + mode + '-' + timestamp + runSuffix;
return [{
  json: {
    started: true,
    async: true,
    mode: mode,
    articles_count: articlesCount,
    expected_folder: expectedFolder,
    started_at: now.toISOString(),
    message: 'Workflow demarre en background sur n8n. Le browser doit poller /api/last-result pour recuperer le resultat final.'
  }
}];
